<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTenantVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetCodeVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTypeVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetContentVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetEnabledVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetVersionVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAssetAttributes;
use PHPUnit\Framework\TestCase;

final class TemplateAssetAttributesUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new TemplateAssetAttributes();
        $tenantOneValue = new TenantRef('one');
        $tenantOtherValue = new TenantRef('other');
        $copy = $value->tenant($tenantOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TenantRef('one'), $value->getTenant());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenant());
        $this->assertEquals(new TenantRef('one'), $value->getTenantOrDefault(TemplateAssetTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenantOrDefault(TemplateAssetTenantVO::from($tenantOtherValue))->value());
        $value->unsetTenant();
        $this->assertEquals(new TenantRef('other'), $value->getTenantOrDefault(TemplateAssetTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('one'), $value->getTenantOrDefault(TemplateAssetTenantVO::from($tenantOtherValue))->value());
        $codeOneValue = 'one';
        $codeOtherValue = 'other';
        $copy = $value->code($codeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getCode());
        $this->assertNotEquals('other', $value->getCode());
        $this->assertEquals('one', $value->getCodeOrDefault(TemplateAssetCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('other', $value->getCodeOrDefault(TemplateAssetCodeVO::from($codeOtherValue))->value());
        $value->unsetCode();
        $this->assertEquals('other', $value->getCodeOrDefault(TemplateAssetCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('one', $value->getCodeOrDefault(TemplateAssetCodeVO::from($codeOtherValue))->value());
        $typeOneValue = 'one';
        $typeOtherValue = 'other';
        $copy = $value->type($typeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getType());
        $this->assertNotEquals('other', $value->getType());
        $this->assertEquals('one', $value->getTypeOrDefault(TemplateAssetTypeVO::from($typeOtherValue))->value());
        $this->assertNotEquals('other', $value->getTypeOrDefault(TemplateAssetTypeVO::from($typeOtherValue))->value());
        $value->unsetType();
        $this->assertEquals('other', $value->getTypeOrDefault(TemplateAssetTypeVO::from($typeOtherValue))->value());
        $this->assertNotEquals('one', $value->getTypeOrDefault(TemplateAssetTypeVO::from($typeOtherValue))->value());
        $contentOneValue = 'store://bin';
        $contentOtherValue = 'store://obin';
        $copy = $value->content($contentOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('store://bin', $value->getContent());
        $this->assertNotEquals('store://obin', $value->getContent());
        $this->assertEquals('bin', $value->getContentOrDefault(TemplateAssetContentVO::from($contentOtherValue))->value());
        $this->assertNotEquals('obin', $value->getContentOrDefault(TemplateAssetContentVO::from($contentOtherValue))->value());
        $value->unsetContent();
        $this->assertEquals('obin', $value->getContentOrDefault(TemplateAssetContentVO::from($contentOtherValue))->value());
        $this->assertNotEquals('bin', $value->getContentOrDefault(TemplateAssetContentVO::from($contentOtherValue))->value());
        $enabledOneValue = true;
        $enabledOtherValue = false;
        $copy = $value->enabled($enabledOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isEnabled());
        $this->assertNotEquals(false, $value->isEnabled());
        $this->assertEquals(true, $value->getEnabledOrDefault(TemplateAssetEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(false, $value->getEnabledOrDefault(TemplateAssetEnabledVO::from($enabledOtherValue))->value());
        $value->unsetEnabled();
        $this->assertEquals(false, $value->getEnabledOrDefault(TemplateAssetEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(true, $value->getEnabledOrDefault(TemplateAssetEnabledVO::from($enabledOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrDefault(TemplateAssetVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrDefault(TemplateAssetVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrDefault(TemplateAssetVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrDefault(TemplateAssetVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
